#include <ctype.h>

class text_file
{
  char io[64];
  char the_stash[52];
  int my_stash;
  char *buf;
  int bufpos;
  int bufamt;
  bool use_stash;
  int pushbackdata;

public:
  char peek_char();
  char read_char();
  void read(int *i);

private:
  void eat_whitespace();
  bool at_eof() const
  {
    return use_stash ? (bufpos >= bufamt && *(const bool *)(the_stash + 16))
                     : (bufpos >= bufamt && *(const bool *)(io + 16));
  }
};

void error(const char *, ...);

__asm__(".equ peek_char__9text_file, 0x00338110");
__asm__(".equ read_char__9text_file, 0x00338138");
__asm__(".equ eat_whitespace__9text_file, 0x00337D20");
__asm__(".equ error__FPCce, 0x001DFBD8");

#define ISDIGIT isdigit

void text_file::read(int* i)
{
  int ret=0;
  bool negative;
  bool found=false;

  eat_whitespace();

  negative=false;
  if (peek_char()=='-') { negative=true; read_char(); }
  else if (peek_char()=='+') { negative=false; read_char(); }

  while (ISDIGIT(peek_char()) && !at_eof())
  {
    found=true;
    ret=ret*10+(read_char()-'0');
  }

  if (!found)
    error("Integer value expected.");

  *i=negative ? -ret : ret;
}
